function deepClone(obj) {
  if (obj === null || obj === undefined) return obj;
  if (typeof obj === 'object') {
    if (Array.isArray(obj)) {
      return obj.map(item => deepClone(item));
    } else {
      return Object.entries(obj).map(([key, value]) => [
        key,
        deepClone(value)
      ]).reduce((acc, [k, v]) => {
        acc[k] = v;
        return acc;
      }, {});
    }
  }
  return obj;
}
